const categories = [
  'Solitude & Self-Discovery',
  'Unspoken Feelings & Goodbyes',
  'Late Night Epiphanies',
  'Silent Battles & Healing',
  'The Cosmic Perspective'
];

const voices = [
  'en-US-ChristopherNeural',
  'en-US-JennyNeural',
  'en-GB-RyanNeural',
  'en-US-GuyNeural'
];

const inputData = $input.item.json || {};
const query = inputData.query || {};
const body = inputData.body || inputData;

const selectedCategory = body.category || query.category || categories[Math.floor(Math.random() * categories.length)];
const selectedVoice = body.voice || query.voice || voices[Math.floor(Math.random() * voices.length)];
const customText = body.custom_text || query.custom_text || '';
const title = body.title || query.title || '';

return {
  json: {
    category: selectedCategory,
    voice: selectedVoice,
    custom_text: customText,
    title: title,
    job_id: `job_${Date.now()}`,
    triggered_at: new Date().toISOString()
  }
};

const videoMeta = $input.item.json;
const files = videoMeta.files || {};

const formattedTags = Array.isArray(videoMeta.hashtags) 
  ? videoMeta.hashtags.join(' ') 
  : '#whisprs #poetry #quotes #deepthoughts #reels';

const fbReelsPayload = {
  page_id: 'WHISPRS_PAGE_ID_PLACEHOLDER',
  caption: `${videoMeta.hook}\n\n${videoMeta.title}\n\n"${videoMeta.script}"\n\nFollow @Whisprs for quiet reminders and late-night thoughts. 🖤\n\n${formattedTags}`,
  video_url: `http://localhost:5055/stream/${videoMeta.video_id}.mp4`,
  source_file: files.video_mp4
};

const ytShortsPayload = {
  snippet: {
    title: `${videoMeta.title} | Whisprs Poetry #Shorts`,
    description: `${videoMeta.caption}\n\n#shorts #poetry #whisprs`,
    tags: videoMeta.hashtags || ['whisprs', 'poetry', 'solitude', 'healing'],
    categoryId: '22'
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  }
};

return {
  json: {
    video_id: videoMeta.video_id,
    title: videoMeta.title,
    hook: videoMeta.hook,
    category: videoMeta.category,
    duration_seconds: videoMeta.duration_seconds,
    caption: videoMeta.caption,
    local_video_path: files.video_mp4,
    local_thumb_path: files.thumbnail_jpg,
    stream_url: `http://localhost:5055/stream/${videoMeta.video_id}.mp4`,
    facebook_reels: fbReelsPayload,
    youtube_shorts: ytShortsPayload,
    status: 'READY_TO_PUBLISH'
  },
  binary: $input.item.binary
};
